  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B034",
      "proposed_laureates": ["Francis Halzen", "Albrecht Karle"],
      "assessment": {
        "nobel_worthiness": "High-energy astrophysical neutrinos opened a new observational window on the most energetic cosmic accelerators, with lasting importance for astroparticle physics.",
        "attribution": "Halzen's leadership in developing IceCube and Karle's central experimental contributions make a strong case, while recognizing the essential work of a large collaboration.",
        "maturity": "The detection and astrophysical origin of a diffuse high-energy neutrino flux are supported by sustained observations, though source identification continues.",
        "uncertainties": ["The relative contributions of individual sources and source classes remain unsettled."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B028",
      "proposed_laureates": ["Charles L. Bennett", "David N. Spergel", "Lyman A. Page Jr."],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of the cosmic microwave background established a quantitative foundation for modern precision cosmology.",
        "attribution": "Bennett and Page led the observational effort, while Spergel made a major contribution to extracting cosmological parameters; the mission depended on a broad team.",
        "maturity": "The results have been tested and extended by later CMB experiments and remain central to the standard cosmological model.",
        "uncertainties": ["The awardable contribution should be distinguished from the earlier discovery of CMB anisotropies and from later precision missions."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B047",
      "proposed_laureates": ["Heino Falcke", "James M. Moran", "Sheperd S. Doeleman"],
      "assessment": {
        "nobel_worthiness": "Event Horizon Telescope imaging turned a longstanding prediction about black holes into direct, striking observations and demonstrated a new scale of global interferometry.",
        "attribution": "Falcke helped establish the observing concept, Moran contributed foundational very long baseline interferometry, and Doeleman led the EHT effort; credit must reflect the international collaboration.",
        "maturity": "Images of multiple black-hole environments and continued observations provide substantial confirmation, though the field is still developing.",
        "uncertainties": ["The boundary between foundational technical contributions and the collaboration's collective achievement needs careful treatment."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B029",
      "proposed_laureates": ["Brian D. Metzger", "Daniel Kasen", "Nial R. Tanvir"],
      "assessment": {
        "nobel_worthiness": "Kilonova observations connected neutron-star mergers with heavy-element production and showed the power of combining gravitational-wave and electromagnetic astronomy.",
        "attribution": "Metzger and Kasen developed influential physical interpretations and predictions, while Tanvir led important observational work; discovery and interpretation involved many groups.",
        "maturity": "The 2017 event and subsequent studies provide strong evidence, but the broader population and detailed nucleosynthesis picture are still being established.",
        "uncertainties": ["The division of credit across prediction, first observation, and follow-up is complex."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B038",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement, enabling tests of fundamental physics and practical timekeeping at unprecedented accuracy.",
        "attribution": "Katori and Ye independently developed leading approaches and sustained the experimental advances that made the field mature.",
        "maturity": "Clock performance and applications have been repeatedly demonstrated by independent groups, with a clear and continuing legacy.",
        "uncertainties": ["The boundary between foundational clock concepts and later performance milestones should be weighed."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B030",
      "proposed_laureates": ["Alan H. Guth", "Andrei Linde", "Viatcheslav Mukhanov"],
      "assessment": {
        "nobel_worthiness": "Inflation is a powerful framework that explains important features of the early universe and makes connections between particle physics and cosmology.",
        "attribution": "Guth and Linde developed influential versions of the theory, while Mukhanov made seminal contributions to predictions for primordial fluctuations.",
        "maturity": "Several broad consequences are consistent with observations, but distinctive evidence for inflation and its mechanism has not been established.",
        "uncertainties": ["No unique inflationary model or decisive observational signature has been confirmed."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B019",
      "proposed_laureates": ["Juan Ignacio Cirac", "Peter Zoller", "Rainer Blatt"],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computation joined a clear theoretical architecture to precise experimental control and helped establish quantum information as an experimental physics discipline.",
        "attribution": "Cirac and Zoller supplied foundational proposals, and Blatt's experiments demonstrated control of individual ions and quantum logic.",
        "maturity": "The platform is highly developed and independently reproduced, although scalable fault-tolerant computation remains a major challenge.",
        "uncertainties": ["A prize should distinguish the foundational physical achievement from later progress toward useful large-scale machines."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B010",
      "proposed_laureates": ["Artur Ekert", "Charles H. Bennett", "Gilles Brassard"],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution gave quantum information a compelling operational consequence and stimulated lasting advances in quantum communication.",
        "attribution": "Ekert, Bennett, and Brassard made distinct foundational contributions to protocols and their physical interpretation.",
        "maturity": "The principles are well established and implementations have been demonstrated, though practical security depends on devices and operating conditions.",
        "uncertainties": ["The scope of credit for theoretical protocols versus deployed network systems is not straightforward."]
      }
    }
  ]
}
